package com.movieticket.booking;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.Map; import org.springframework.dao.DataIntegrityViolationException;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(IllegalArgumentException.class) public ResponseEntity<?> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));} @ExceptionHandler(java.util.NoSuchElementException.class) public ResponseEntity<?> missing(java.util.NoSuchElementException e){return ResponseEntity.status(404).body(Map.of("error",e.getMessage()));} @ExceptionHandler(DataIntegrityViolationException.class) public ResponseEntity<?> conflict(DataIntegrityViolationException e){return ResponseEntity.status(409).body(Map.of("error","Resource conflicts with an existing record"));} }
